"""Four original RGB source views for the road/follow construction.

The caller supplies lossless frame sinks. This helper checks frame identity and
resolution; only subsequent physical review can establish visibility.
"""

from collections import defaultdict
from pathlib import Path
import subprocess
from threading import Condition
from time import monotonic


CAMERAS = {
    'overview': ((-8.0, 0.0, 7.0), (-20.0, 0.0, 0.0), (1920, 1080), 95),
    'approach': ((1.5, 0.0, 2.0), (0.0, 0.0, 0.0), (1280, 720), 90),
    'reference_corner': ((1.5, 1.0, 1.6), (0.0, 0.0, 0.0), (1280, 720), 100),
    'driver_reference': ((0.3, -0.3, 1.5), (0.0, 0.0, 0.0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError('Unknown following source camera')
        path = Path(output) / (name + '.mkv')
        if path.exists():
            raise ValueError('Retain prior following camera source')
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen([
            'ffmpeg', '-nostdin', '-loglevel', 'error', '-y',
            '-f', 'rawvideo', '-pixel_format', 'bgra',
            '-video_size', f'{width}x{height}', '-framerate', '20',
            '-i', 'pipe:0', '-an', '-c:v', 'ffv1', str(path)],
            stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError('Original following camera byte count changed')
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError('Following source encoder failed')


class FollowingCameraCapture:
    def __init__(self, world, carla, ego, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError('Four named source-camera sinks required')
        self.sensors = []
        self.frames = defaultdict(list)
        self.sinks = sinks
        self.condition = Condition()
        self.errors = []
        self.closed = False
        try:
            for name, (location, rotation, size, fov) in CAMERAS.items():
                blueprint = world.get_blueprint_library().find('sensor.camera.rgb')
                blueprint.set_attribute('image_size_x', str(size[0]))
                blueprint.set_attribute('image_size_y', str(size[1]))
                blueprint.set_attribute('fov', str(fov))
                blueprint.set_attribute('sensor_tick', '0.05')
                transform = carla.Transform(carla.Location(*location),
                                            carla.Rotation(*rotation))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                if sensor is None:
                    raise ValueError('Could not spawn source camera: ' + name)
                self.sensors.append(sensor)
                sensor.listen(self._listener(name, size))
        except BaseException:
            self.close()
            raise

    def _listener(self, name, size):
        def receive(image):
            with self.condition:
                if self.closed:
                    return
                try:
                    if (image.width, image.height) != size:
                        raise ValueError('Source camera resolution changed: ' + name)
                    if image.frame in self.frames[name]:
                        raise ValueError('Duplicate original source camera frame: ' + name)
                    self.sinks[name].write(image)
                    self.frames[name].append(image.frame)
                except BaseException as error:
                    self.errors.append(error)
                finally:
                    self.condition.notify_all()
        return receive

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError('Source camera callback failed') from self.errors[0]
                if all(frame in self.frames[name] for name in CAMERAS):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError('Missing original source camera frame')
                self.condition.wait(remaining)

    def verify(self, expected_frames):
        if not expected_frames or self.errors:
            raise ValueError('No original Native frames to verify')
        for name in CAMERAS:
            if self.frames[name] != expected_frames:
                raise ValueError('Missing or extra original source camera frames: ' + name)
        return {name: len(expected_frames) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                try:
                    sensor.stop()
                finally:
                    sensor.destroy()

"""Physical request plan for two distinct right passes of one fixed vehicle.

This is an engineering controller plan, not evidence that a pass or violation
occurred. A Native runner must retain body/road geometry and check transitions.
"""

from dataclasses import dataclass
from math import isfinite


@dataclass(frozen=True)
class Phase:
    name: str
    start_m: float
    end_m: float
    ego_target: str
    ego_speed_mps: float
    lead_speed_mps: float


PHASES = (
    Phase('approach', 0, 260, 'paved_lane', 16, 16),
    Phase('first_right_pass_request', 260, 450, 'right_of_paved_edge', 24, 10),
    Phase('first_reentry', 450, 500, 'paved_lane', 12, 12),
    Phase('lead_reclaim_request', 500, 580, 'right_of_paved_edge', 6, 20),
    Phase('second_reentry', 580, 1850, 'paved_lane', 25, 25),
    Phase('second_right_pass_request', 1850, 2020, 'right_of_paved_edge', 24, 10),
    Phase('exit', 2020, 2200, 'paved_lane', 16, 16),
)


def validate_schedule(phases=PHASES):
    if len(phases) != 7 or phases[0].start_m != 0:
        raise ValueError('Two-pass phase inventory differs')
    if any(a.end_m != b.start_m for a, b in zip(phases, phases[1:])):
        raise ValueError('Two-pass route station schedule has a gap or overlap')
    labels = [p.name for p in phases]
    if labels.index('first_right_pass_request') >= labels.index('first_reentry') or labels.index('second_reentry') >= labels.index('second_right_pass_request'):
        raise ValueError('Two-pass reentry does not separate pass requests')
    for phase in phases:
        if phase.start_m >= phase.end_m or phase.ego_target not in ('paved_lane', 'right_of_paved_edge'):
            raise ValueError('Invalid two-pass target')
        if not all(isfinite(v) and 0 <= v <= 30 for v in (phase.ego_speed_mps, phase.lead_speed_mps)):
            raise ValueError('Invalid controller speed request')
    return True


def phase_at(ego_station_m):
    validate_schedule()
    if not isfinite(ego_station_m):
        raise ValueError('Missing finite ego route station')
    for phase in PHASES:
        if phase.start_m <= ego_station_m < phase.end_m:
            return phase
    raise ValueError('Ego route station outside two-pass request plan')


def transition_guard(previous, current, ego_minus_lead_m, ego_right_of_mapped_edge_m):
    """Fail closed when original geometry contradicts an intended phase.

    `ego_minus_lead_m` is signed route progress: negative means lead ahead.
    Edge clearance is measured from retained Native road geometry, not inferred
    from a requested lateral target. Actual pavement material remains pixel review.
    """
    if previous == current:
        return True
    if current not in {p.name for p in PHASES}:
        raise ValueError('Unknown physical phase')
    if not all(isfinite(v) for v in (ego_minus_lead_m, ego_right_of_mapped_edge_m)):
        raise ValueError('Missing original vehicle or mapped-edge geometry')
    if current == 'first_right_pass_request' and ego_minus_lead_m >= -5:
        raise ValueError('Fixed vehicle is not ahead before first pass')
    if current == 'first_reentry' and ego_minus_lead_m <= 5:
        raise ValueError('First order reversal was not realized')
    if current == 'lead_reclaim_request' and ego_right_of_mapped_edge_m > 0:
        raise ValueError('First mapped-edge reentry was not realized')
    if current == 'second_reentry' and ego_minus_lead_m >= -5:
        raise ValueError('Fixed vehicle did not reclaim the lead')
    if current == 'second_right_pass_request' and (ego_minus_lead_m >= -5 or ego_right_of_mapped_edge_m > 0):
        raise ValueError('Second pass lacks reset and mapped-edge reentry')
    return True

"""Derive unreviewed two-pass candidates from retained original source rows."""

from math import isfinite

REQUESTS = ('first_right_pass_request', 'second_right_pass_request')


def candidates(rows, frame_map):
    if not isinstance(rows, list) or not isinstance(frame_map, list) or len(rows) != len(frame_map) or len(rows) < 6:
        raise ValueError('Original pass source/frame map coverage differs')
    ego_ids = {row.get('ego_actor_id') for row in rows}
    target_ids = {row.get('fixed_overtaken_actor_id') for row in rows}
    if len(ego_ids) != 1 or None in ego_ids or len(target_ids) != 1 or None in target_ids:
        raise ValueError('Fixed ego or overtaken vehicle identity differs')
    previous = None
    for row, video in zip(rows, frame_map):
        frame = row.get('frame')
        time_s = row.get('time_s')
        if frame != video.get('carla_frame') or time_s != video.get('time_s'):
            raise ValueError('Original pass/video frame join differs')
        if type(frame) is not int or not isinstance(time_s, (int, float)) or not isfinite(time_s):
            raise ValueError('Original pass frame/time missing')
        if previous is not None and (frame != previous[0] + 1 or time_s <= previous[1]):
            raise ValueError('Original pass source is discontinuous')
        previous = (frame, time_s)
        for key in ('ego_station_m', 'lead_station_m', 'right_of_mapped_road_edge_m'):
            value = row.get(key)
            if not isinstance(value, (int, float)) or not isfinite(value):
                raise ValueError('Original pass geometry missing: '+key)
        if not isinstance(row.get('mapped_driving_edge_xy_m'), list) or not isinstance(row.get('mapped_road_edge_xy_m'), list):
            raise ValueError('Driving and mapped road edges must be separate sources')
    episodes = []
    for name in REQUESTS:
        selected = [row for row in rows if row.get('requested_phase') == name]
        if len(selected) < 2:
            return {'status':'unverified','reason':'Missing original phase: '+name,
                    'episodes':episodes,'fixed_overtaken_actor_id':next(iter(target_ids))}
        first, last = selected[0], selected[-1]
        before = first['ego_station_m'] - first['lead_station_m']
        after = last['ego_station_m'] - last['lead_station_m']
        beyond = [row['frame'] for row in selected if row['right_of_mapped_road_edge_m'] > 0]
        if before >= -5 or after <= 5 or not beyond:
            return {'status':'unverified','reason':'Original order reversal or mapped-edge crossing absent: '+name,
                    'episodes':episodes,'fixed_overtaken_actor_id':next(iter(target_ids))}
        episodes.append({'start_frame':first['frame'],'end_frame':last['frame'],
                         'target_vehicle_id':next(iter(target_ids)),
                         'before_gap_m':before,'after_gap_m':after,
                         'rightward_separation_m':max(row['right_of_mapped_road_edge_m'] for row in selected),
                         'off_pavement_frames':beyond,
                         'surface_status':'unreviewed; mapped edge is not a pavement verdict'})
    first_end, second_start = episodes[0]['end_frame'], episodes[1]['start_frame']
    middle = [row for row in rows if first_end < row['frame'] < second_start]
    if not middle or not any(row['right_of_mapped_road_edge_m'] <= 0 for row in middle):
        return {'status':'unverified','reason':'No original mapped-edge reentry between requests',
                'episodes':episodes,'fixed_overtaken_actor_id':next(iter(target_ids))}
    if not any(row['ego_station_m'] - row['lead_station_m'] < -5 for row in middle):
        return {'status':'unverified','reason':'Fixed vehicle did not reclaim the lead',
                'episodes':episodes,'fixed_overtaken_actor_id':next(iter(target_ids))}
    return {'status':'candidate','episodes':episodes,
            'fixed_overtaken_actor_id':next(iter(target_ids)),
            'passing_violation_decided':False,'pavement_surface_decided':False,
            'immediate_hazard_decided':False,'aggressive_driving_decided':False}
